        return parts

    rparts = intervals(row_seps, h)
    cparts = intervals(col_seps, w)
    panels = [
        [[grid[r][c] for c in range(c0, c1)] for r in range(r0, r1)]
        for r0, r1 in rparts
        for c0, c1 in cparts
    ]

    nr, nc = len(rparts), len(cparts)

    # Clockwise traversal of the panel arrangement, starting at bottom-left.
    positions = []
    top, bottom, left, right = 0, nr - 1, 0, nc - 1
    while top <= bottom and left <= right:
        if top == bottom:
            positions.extend((top, c) for c in range(left, right + 1))
            break
        if left == right:
            positions.extend((r, left) for r in range(bottom, top - 1, -1))
            break
        positions.extend((r, left) for r in range(bottom, top - 1, -1))
        positions.extend((top, c) for c in range(left + 1, right + 1))
        positions.extend((r, right) for r in range(top + 1, bottom + 1))
        positions.extend((bottom, c) for c in range(right - 1, left, -1))
        top += 1
        bottom -= 1
        left += 1
        right -= 1

    ordered = [panels[r * nc + c] for r, c in positions]
    ph, pw = len(ordered[0]), len(ordered[0][0])

    def foreground(v):
        return v != 7 and v != 6

    def edge_counts(panel, axis):
        if axis == "H":
            incoming = sum(foreground(panel[r][0]) for r in range(len(panel)))
            outgoing = sum(foreground(panel[r][-1]) for r in range(len(panel)))
        else:
            incoming = sum(foreground(v) for v in panel[0])
            outgoing = sum(foreground(v) for v in panel[-1])
        return incoming, outgoing

    horizontal_total = sum(
        edge_counts(p, "H")[0] + edge_counts(p, "H")[1] for p in ordered
    )
    vertical_total = sum(
        edge_counts(p, "V")[0] + edge_counts(p, "V")[1] for p in ordered
    )
    axis = "H" if horizontal_total >= vertical_total else "V"

    def valid_chain(sequence):
        edges = [edge_counts(p, axis) for p in sequence]
        return (
            edges[0][0] == 0
            and edges[-1][1] == 0
            and all(edges[i][1] == edges[i + 1][0] for i in range(len(edges) - 1))
        )

    # If needed, slide each panel's object along the chain direction to match
    # the number of colored cells on neighboring edges.
    if not valid_chain(ordered):
        candidates = []
        for panel in ordered:
            coords = [
                (r, c)
                for r in range(ph)
                for c in range(pw)
                if foreground(panel[r][c])
            ]
            if not coords:
                candidates.append([0])
            elif axis == "H":
                xs = [c for _, c in coords]
                candidates.append(list(range(-min(xs), pw - 1 - max(xs) + 1)))
            else:
                ys = [r for r, _ in coords]
                candidates.append(list(range(-min(ys), ph - 1 - max(ys) + 1)))

        def shifted(panel, delta):
            result = [[7] * pw for _ in range(ph)]
