                        rr, cc = (r, c + delta) if axis == "H" else (r + delta, c)
                        result[rr][cc] = panel[r][c]
            return result

        best = None

        def search(i, built, shifts, previous_out, cost):
            nonlocal best
            if best is not None and cost > best[0]:
                return
            if i == len(ordered):
                if previous_out == 0:
                    option = (cost, tuple(shifts), built)
                    if best is None or option[:2] < best[:2]:
                        best = option
                return

            for delta in candidates[i]:
                p = shifted(ordered[i], delta)
                incoming, outgoing = edge_counts(p, axis)
                if (i == 0 and incoming != 0) or (i > 0 and incoming != previous_out):
                    continue
                search(i + 1, built + [p], shifts + [delta], outgoing, cost + abs(delta))

        search(0, [], [], None, 0)
        if best is not None:
            ordered = best[2]

    if axis == "H":
        out = []
        for r in range(ph):
            row = []
            for i, panel in enumerate(ordered):
                if i:
                    row.append(6)
                row.extend(panel[r])
            out.append(row)
        return out

    out = []
    for i, panel in enumerate(ordered):
        if i:
            out.append([6] * pw)
        out.extend([row[:] for row in panel])
    return out
