def transform(grid):
    from functools import lru_cache

    h, w = len(grid), len(grid[0])

    def get_parts(separators, length):
        parts = []
        start = 0
        for i, is_separator in enumerate(separators):
            if is_separator:
                if start < i:
                    parts.append((start, i))
                start = i + 1
        if start < length:
            parts.append((start, length))
        return parts

    row_parts = get_parts([all(v == 6 for v in row) for row in grid], h)
    col_parts = get_parts(
        [all(grid[r][c] == 6 for r in range(h)) for c in range(w)], w
    )

    panels = [
        [row[c0:c1] for row in grid[r0:r1]]
        for r0, r1 in row_parts
        for c0, c1 in col_parts
    ]

    def solve_axis(axis):
        options = []

        for panel in panels:
            ph, pw = len(panel), len(panel[0])
            coords = [
                (r, c)
                for r in range(ph)
                for c in range(pw)
                if panel[r][c] != 7
            ]

            if not coords:
                deltas = [0]
            elif axis == "H":
                min_c = min(c for _, c in coords)
                max_c = max(c for _, c in coords)
                deltas = range(-min_c, pw - 1 - max_c + 1)
            else:
                min_r = min(r for r, _ in coords)
                max_r = max(r for r, _ in coords)
                deltas = range(-min_r, ph - 1 - max_r + 1)

            panel_options = []
            for delta in deltas:
                moved = [[7] * pw for _ in range(ph)]
                for r, c in coords:
                    rr, cc = (r, c + delta) if axis == "H" else (r + delta, c)
                    moved[rr][cc] = panel[r][c]

                if axis == "H":
                    incoming = tuple(moved[r][0] != 7 for r in range(ph))
                    outgoing = tuple(moved[r][-1] != 7 for r in range(ph))
                else:
                    incoming = tuple(v != 7 for v in moved[0])
                    outgoing = tuple(v != 7 for v in moved[-1])

                panel_options.append({
                    "delta": delta,
                    "panel": moved,
                    "incoming": incoming,
                    "outgoing": outgoing,
                })
            options.append(panel_options)

        n = len(panels)
        full_mask = (1 << n) - 1
        empty = tuple(False for _ in options[0][0]["incoming"])

        def path_key(path):
            return tuple((i, options[i][k]["delta"]) for i, k in path)

        @lru_cache(None)
        def best_tail(mask, last_panel, last_option):
            last = options[last_panel][last_option]
            if mask == full_mask:
                return (0, ()) if last["outgoing"] == empty else None
            if last["outgoing"] == empty:
                return None

            best = None
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                for option_index, option in enumerate(options[nxt]):
                    if option["incoming"] != last["outgoing"]:
                        continue
                    tail = best_tail(mask | (1 << nxt), nxt, option_index)
                    if tail is None:
                        continue
                    path = ((nxt, option_index),) + tail[1]
                    candidate = (
                        abs(option["delta"]) + tail[0],
                        path,
                    )
                    if best is None or (
                        candidate[0], path_key(candidate[1])
                    ) < (best[0], path_key(best[1])):
                        best = candidate
            return best

        best = None
        for i in range(n):
            for option_index, option in enumerate(options[i]):
                if option["incoming"] != empty:
                    continue
                tail = best_tail(1 << i, i, option_index)
                if tail is None:
                    continue
                path = ((i, option_index),) + tail[1]
                candidate = (abs(option["delta"]) + tail[0], path)
                if best is None or (
                    candidate[0], path_key(candidate[1])
                ) < (best[0], path_key(best[1])):
                    best = candidate

        if best is None:
            return None

        ordered = [options[i][k]["panel"] for i, k in best[1]]
        return best[0], ordered

    horizontal = solve_axis("H")
    vertical = solve_axis("V")

    if horizontal is None and vertical is None:
        return [row[:] for row in grid]

    if vertical is None or (
        horizontal is not None and horizontal[0] <= vertical[0]
    ):
        axis = "H"
        ordered = horizontal[1]
    else:
        axis = "V"
        ordered = vertical[1]

    ph, pw = len(ordered[0]), len(ordered[0][0])

    if axis == "H":
        result = []
        for r in range(ph):
            row = []
            for i, panel in enumerate(ordered):
                if i:
                    row.append(6)
                row.extend(panel[r])
            result.append(row)
        return result

    result = []
    for i, panel in enumerate(ordered):
        if i:
            result.append([6] * pw)
        result.extend([row[:] for row in panel])
    return result
